//! English inflection, learned from Wiktionary.
//!
//! Generated by morphe from the Kaikki English dump of 2026-10-03. Do not edit.
//! Every function is total: unknown words are inflected by prediction, and
//! the `_scored` versions give every candidate with a confidence, best first.
//! Variant confidences reflect Wiktionary's listing order, not measured usage.
//!
//! Data: Wiktionary contributors, CC BY-SA 4.0, via kaikki.org.

#![forbid(unsafe_code)]

pub use morphe::{Options, Scored};
use std::sync::OnceLock;

static DATA: &[u8] = include_bytes!("model.bin");

/// The trained model, for dynamic queries.
pub fn model() -> Option<&'static morphe::Model> {
    static MODEL: OnceLock<Option<morphe::Model>> = OnceLock::new();
    MODEL.get_or_init(|| morphe::Model::decode(DATA)).as_ref()
}

fn best(scored: Scored<String>, word: &str) -> String {
    scored.into_iter().next().map_or_else(|| word.split(',').next().unwrap_or(word).trim().to_string(), |x| x.0)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Number {
    Singular,
    Plural,
}

impl Number {
    pub const ALL: [Self; 2] = [Self::Singular, Self::Plural];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Person {
    First,
    Second,
    Third,
}

impl Person {
    pub const ALL: [Self; 3] = [Self::First, Self::Second, Self::Third];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Tense {
    Present,
    Past,
}

impl Tense {
    pub const ALL: [Self; 2] = [Self::Present, Self::Past];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Degree {
    Comparative,
    Superlative,
}

impl Degree {
    pub const ALL: [Self; 2] = [Self::Comparative, Self::Superlative];
}

/// Settings for systematic choices. `English::default()` is what the free functions use.
#[derive(Clone, Copy, Debug, Default)]
pub struct English {
    pub options: Options,
}

impl English {
    /// Keep stress and similar marks in the output (on by default).
    pub fn marks(mut self, on: bool) -> Self {
        self.options.marks = on;
        self
    }

    /// A noun form.
    pub fn noun_scored(&self, word: &str, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (number,) {
            (Number::Plural,) => Some(0),
            _ => None,
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form. The best candidate; the word itself if nothing is known.
    pub fn noun(&self, word: &str, number: Number) -> String {
        best(self.noun_scored(word, number), word)
    }

    /// Dictionary spelling of a noun (with stress marks where the data has them).
    pub fn noun_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(0, word)).unwrap_or_else(|| word.to_string())
    }

    /// A verb form.
    pub fn verb_scored(&self, word: &str, tense: Tense, person: Person, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (tense, person, number,) {
            (Tense::Present, Person::First, Number::Singular,) => Some(0),
            (Tense::Present, Person::First, Number::Plural,) => Some(1),
            (Tense::Present, Person::Second, Number::Singular,) => Some(2),
            (Tense::Present, Person::Second, Number::Plural,) => Some(3),
            (Tense::Present, Person::Third, Number::Singular,) => Some(4),
            (Tense::Present, Person::Third, Number::Plural,) => Some(5),
            (Tense::Past, Person::First, Number::Singular,) => Some(6),
            (Tense::Past, Person::First, Number::Plural,) => Some(7),
            (Tense::Past, Person::Second, Number::Singular,) => Some(8),
            (Tense::Past, Person::Second, Number::Plural,) => Some(9),
            (Tense::Past, Person::Third, Number::Singular,) => Some(10),
            (Tense::Past, Person::Third, Number::Plural,) => Some(11),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A verb form. The best candidate; the word itself if nothing is known.
    pub fn verb(&self, word: &str, tense: Tense, person: Person, number: Number) -> String {
        best(self.verb_scored(word, tense, person, number), word)
    }

    /// A verb form (participle).
    pub fn verb_participle_scored(&self, word: &str, tense: Tense) -> Scored<String> {
        let cell: Option<u32> = match (tense,) {
            (Tense::Present,) => Some(12),
            (Tense::Past,) => Some(13),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A verb form (participle). The best candidate; the word itself if nothing is known.
    pub fn verb_participle(&self, word: &str, tense: Tense) -> String {
        best(self.verb_participle_scored(word, tense), word)
    }

    /// Dictionary spelling of a verb (with stress marks where the data has them).
    pub fn verb_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(1, word)).unwrap_or_else(|| word.to_string())
    }

    /// A adj form.
    pub fn adj_scored(&self, word: &str, degree: Degree) -> Scored<String> {
        let cell: Option<u32> = match (degree,) {
            (Degree::Comparative,) => Some(0),
            (Degree::Superlative,) => Some(1),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(2, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A adj form. The best candidate; the word itself if nothing is known.
    pub fn adj(&self, word: &str, degree: Degree) -> String {
        best(self.adj_scored(word, degree), word)
    }

    /// Dictionary spelling of a adj (with stress marks where the data has them).
    pub fn adj_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(2, word)).unwrap_or_else(|| word.to_string())
    }

    /// A adv form.
    pub fn adv_scored(&self, word: &str, degree: Degree) -> Scored<String> {
        let cell: Option<u32> = match (degree,) {
            (Degree::Comparative,) => Some(0),
            (Degree::Superlative,) => Some(1),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(3, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A adv form. The best candidate; the word itself if nothing is known.
    pub fn adv(&self, word: &str, degree: Degree) -> String {
        best(self.adv_scored(word, degree), word)
    }

    /// Dictionary spelling of a adv (with stress marks where the data has them).
    pub fn adv_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(3, word)).unwrap_or_else(|| word.to_string())
    }

}

